import numpy as np

class FedProx:
    def __init__(self, mu=0.01):
        self.mu = mu
    def local_train_prox(self, global_w, local_data, epochs, lr):
        local_w = {k: v.copy() for k, v in global_w.items()}
        for epoch in range(epochs):
            X, y = local_data
            logits = X @ local_w['W1'] + local_w['b1']
            H = np.maximum(0, logits)
            out = H @ local_w['W2'] + local_w['b2']
            d_out = 2 * (out - y) / len(y)
            dW2 = H.T @ d_out
            db2 = np.sum(d_out, axis=0)
            dH = d_out @ local_w['W2'].T
            d_logits = dH * (H > 0)
            dW1 = X.T @ d_logits
            db1 = np.sum(d_logits, axis=0)
            grads = {'W1': dW1, 'b1': db1, 'W2': dW2, 'b2': db2}
            for k in local_w:
                prox_grad = self.mu * (local_w[k] - global_w[k])
                local_w[k] -= lr * (grads[k] + prox_grad)
        return local_w
    def heterogeneous_train(self, global_w, client_data_list, lr):
        client_weights = []
        for data in client_data_list:
            epochs = np.random.randint(1, 5)
            w = self.local_train_prox(global_w, data, epochs, lr)
            client_weights.append(w)
        return client_weights
    def aggregate(self, client_weights, sample_sizes):
        total = sum(sample_sizes)
        return {k: sum(n * w[k] for n, w in zip(sample_sizes, client_weights)) / total for k in client_weights[0]}
